style.css:
@-moz-document domain("claude.ai") {
/* claude.ai stores its colors as HSL numbers, so we override those */
  :root, [data-theme="light"], .light {
    --bg-000: 45 100% 98%;   /* cream card */
    --bg-100: 44 90% 94%;    /* page */
    --bg-200: 42 85% 89%;
    --bg-300: 40 80% 84%;
    --bg-400: 38 75% 78%;
    --bg-500: 36 70% 72%;
    --text-000: 20 40% 10%;
    --text-100: 20 35% 14%;
    --text-200: 22 25% 30%;
    --text-300: 24 20% 40%;
    --text-400: 26 15% 50%;
    --text-500: 28 12% 58%;
    --accent-main-000: 24 95% 46%;
    --accent-main-100: 28 96% 52%;   /* mango orange */
    --accent-main-200: 36 98% 55%;
    --accent-secondary-100: 120 40% 36%; /* leaf green */
    --accent-pro-100: 340 80% 64%;       /* pink */
    --border-100: 30 60% 40%;
    --border-200: 30 60% 40%;
    --border-300: 30 50% 45%;
  }
  [data-theme="dark"], .dark {
    --bg-000: 28 30% 14%;
    --bg-100: 25 30% 9%;     /* dark mango skin */
    --bg-200: 25 28% 7%;
    --bg-300: 25 26% 5%;
    --bg-400: 25 24% 4%;
    --bg-500: 25 22% 3%;
    --text-000: 45 100% 97%;
    --text-100: 44 80% 92%;
    --text-200: 42 45% 78%;
    --text-300: 40 30% 66%;
    --text-400: 38 20% 55%;
    --text-500: 36 15% 46%;
    --accent-main-000: 36 98% 50%;
    --accent-main-100: 40 98% 58%;   /* ripe yellow */
    --accent-main-200: 30 96% 60%;
    --accent-secondary-100: 110 45% 52%;
    --accent-pro-100: 340 85% 70%;
    --border-100: 40 60% 70%;
    --border-200: 40 60% 70%;
    --border-300: 40 50% 60%;
  }

  /* text selection = pink misprint vibe */
  ::selection { background: #ff8fb1; color: #2a140a; }

  /* chunky flat input box with offset shadow */
  fieldset > div, [contenteditable="true"] {
    caret-color: #f28c1b;
  }
  fieldset > div:first-child {
    border-radius: 18px !important;
    box-shadow: 5px 5px 0 #ff8fb1 !important;
  }

  /* your message bubbles */
  [data-testid="user-message"] {
    border-left: 4px solid #4f9a3a;
    padding-left: 10px;
  }

  /* code blocks */
  pre, code { border-radius: 10px !important; }
  pre { box-shadow: 4px 4px 0 #f6b21a; }

  /* scrollbar */
  * { scrollbar-color: #f28c1b transparent; scrollbar-width: thin; }
}
